import sys,pathlib,json,datetime
sys.path.insert(0,str(pathlib.Path('research/python').resolve()))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
t=read('dist/data/snirh-telemetry.json');r=read('dist/data/national-readiness.json');h=read('dist/data/coimbra-calibration-data.json');stations={s['id']:s for s in t['stations']}
fig,axs=plt.subplots(2,1,figsize=(10,7),layout='constrained')
for sid,q,axis in [('1627759222','level_m',0),('1627743384','outflow_m3s',1),('1627759328','outflow_m3s',1),('1627743374','outflow_m3s',1)]:
 s=stations[sid];rows=next(p['rows'] for p in s['series'] if p['quantity']==q);axs[axis].plot([datetime.datetime.fromisoformat(p['observed_at'].replace('Z','+00:00')) for p in rows],[p['value'] for p in rows],label=s['name'],lw=1.7)
for ax in axs:ax.grid(alpha=.2);ax.legend(fontsize=8);ax.xaxis.set_major_formatter(mdates.DateFormatter('%d/%m %Hh',tz=datetime.timezone.utc));ax.tick_params(axis='x',labelsize=8)
axs[0].set(title='Santa Clara · nível real publicado pela APA/SNIRH',ylabel='Altura na régua (m)');axs[1].set(title='Efluentes publicados · não somar barragens em cascata',ylabel='Caudal efluente (m³/s)',xlabel='Hora UTC · origem interpretada em Europe/Lisbon')
fig.savefig('dist/figures/08_snirh_observacoes.png',dpi=160);plt.close(fig)
rows=''.join(f"<tr><td>{b['basin']}</td><td>{b['stations']}</td><td>{b['fresh_levels']}</td><td>{b['fresh_flows']}</td><td>{b['fresh_releases']}</td><td>Por validar</td></tr>" for b in r['basins'])
section=f'''<section id="snirh-integration"><h2>Ligação real APA/SNIRH e avaliação da calibração</h2><p>Recolha {t['retrieved_at']}: {t['catalogue_count']} estações hidrométricas/albufeiras do InfoÁgua; {r['fresh_stations']} com alguma grandeza recente, janela máxima 3 h. A idade é calculada por medição, não pela hora de descarga. Publicação não implica validação laboratorial ou confirmação operacional pela APA.</p><img src="figures/08_snirh_observacoes.png" alt="Séries reais de nível de Santa Clara e efluentes de Aguieira, Raiva e açude de Coimbra"><p>O coletor lê os dados JSON das páginas públicas oficiais, sem executar JavaScript externo. Não foi encontrada documentação de uma API pública contratual; o adaptador de HTML é versionado, verifica unidades e conserva URL, hash e data. Consulta nacional com três pedidos simultâneos; por defeito a cada 15 min. Um intervalo de hora ambígua na mudança de verão/inverno é rejeitado. O fuso Europe/Lisbon é uma hipótese explícita porque a origem não inclui offset.</p><p><b>Santa Clara (12G/04H):</b> zero da escala SNIRH de 15,45 m desde 22/06/2004. A altitude publicada é zero + altura medida; a transformação para o referencial EGM2008 do DSM continua por determinar. Não se usa a diferença entre duas referências verticais como erro de calibração.</p><p><b>Calibração hidráulica não concluída:</b> consulta diária 2016–2025, parâmetros SNIRH 1845/1850: {h['assessment']['daily_level_count']} níveis, {h['assessment']['daily_flow_count']} caudais, {h['assessment']['usable_same_station_daily_pairs']} pares simultâneos. As curvas de vazão históricas encontradas terminam em 30/09/1985; não são aplicadas ao nível de 2026. O treino de uma relação nível–caudal exige pares da mesma estação e referencial, amplitudes relevantes e pelo menos três eventos independentes. Um evento fica reservado para validação; extrapolação proibida. O ajustador foi testado com dados sintéticos identificados apenas nos testes, não usado para fabricar uma calibração real.</p><p>Aguieira e Raiva estão em cascata; não somar as suas descargas. O efluente de Fronhas não consta da janela consultada. Caudal publicado no açude de Coimbra não é automaticamente o caudal da secção de Santa Clara nem de todos os 16 km do piloto. A posição das comportas, remanso e trânsito de cheia exigem modelação própria. As medições estão ligadas e visíveis, mas ainda não são assimiladas na mancha experimental. A vista atual mostra observações e mantém bloqueada a mancha sem validação.</p><h3>Preparação da expansão nacional</h3><p>Inventário de 262 bacias APA de nível 3 no continente: interseção geográfica com estações, disponibilidade de nível/caudal/efluente e interseção com o piloto. Uma estação dentro de um polígono não prova representatividade hidrológica. Não se extrapola o canal de Coimbra para outras bacias. Cada troço exige terreno e batimetria, ligação à rede, transformação vertical, condições de fronteira, calibração por eventos e validação independente da mancha antes de cruzar CAOP/BGRI. Açores e Madeira: integrar fontes regionais e cartografia própria; ainda sem cobertura hidráulica.</p><table><tr><th>Área da fonte</th><th>Estações</th><th>Níveis recentes</th><th>Caudais recentes</th><th>Efluentes recentes</th><th>Hidráulica</th></tr>{rows}</table><p>Ficheiros públicos: <a href="data/snirh-telemetry.json">séries e proveniência</a>, <a href="data/coimbra-calibration-data.json">histórico de calibração</a>, <a href="data/national-readiness.json">avaliação</a>, <a href="data/national-expansion.geojson">inventário das 262 bacias</a>. Não há freguesias classificadas como inundadas atualmente a partir de chuva, armazenamento ou cota não reconciliada.</p><p>Fontes primárias: <a href="https://infoagua.apambiente.pt/pt/cheias/cheias-pesquisa">APA InfoÁgua</a>; <a href="https://snirh.apambiente.pt/snirh/_dadosbase/site/simplex.php?OBJINFO=INFO&amp;FILTRA_SITE=1627759222&amp;FILTRA_COVER=920123705">SNIRH ficha Santa Clara</a>; <a href="https://snirh.apambiente.pt/snirh/_dadosbase/site/janela_curvasvazao.php?sites=1627759222&amp;pars=&amp;tmin=01/01/2016&amp;tmax=24/10/2026">curvas históricas de vazão</a>.</p></section>'''
p=pathlib.Path('dist/report.html');text=p.read_text(encoding='utf-8');start=text.find('<section id="snirh-integration">')
if start>=0:text=text[:start]+text[text.index('</section>',start)+10:]
text=text.replace('</body>',section+'</body>') if '</body>' in text else text+section;p.write_text(text,encoding='utf-8')
pathlib.Path('docs/SNIRH_CALIBRACAO_EXPANSAO.md').write_text('# Ligação SNIRH, calibração e expansão\n\n'+section+'\n\nReprodução: node tools/snirh.cjs; node tools/snirh-history.cjs (histórico, não em cada recolha); node tools/readiness.cjs; python tools/expansion.py. Ajustador: engine/calibration.py. Este relatório é um snapshot datado, o mapa atualiza as medições.\n',encoding='utf-8')
